#!/usr/bin/env bash
# Phase 4 launches. Every run is resumable and skipped when finished, so a launch can simply be repeated.
# Usage (from the repo root): bash scripts/run_phase4.sh <launch> [python]
# Do not edit this file while a launch is running (bash reads it as it goes).
set -euo pipefail

main() {
  local what=$1 PY=${2:-python}
  export PYTHONPATH=src
  case "$what" in
    data)      $PY -m phase4.generate && $PY -m phase4.analysis data ;;
    # 4.1 size check: 20 minutes each, one after the other so that neither slows the other
    size)      for s in small medium; do
                 $PY -m phase4.train --name "size_$s" --size "$s" --max-minutes 20 --no-plateau; done ;;
    size-large) $PY -m phase4.train --name size_large --size large --max-minutes 20 --no-plateau ;;
    # 4.1 training to the plateau; one launch stays under 2 hours and the next one resumes
    sft)       $PY -m phase4.train --name sft --size "${SIZE:?set SIZE=small|medium|large}" --launch-minutes 110 ;;
    sft-report) $PY -m phase4.analysis sft --size "${SIZE:-medium}" ;;
    sampler)   $PY -m phase4.sampler_eval --size "${SIZE:-medium}" ;;   # 4.2, about 11 minutes
    # 4.4: the seven phase 3 objectives from the plateau model, hard band, 4 sampler steps. One seed per launch
    # (SEED=0|1|2, about 7 minutes per run alone); the three seeds can run side by side.
    rl44)      local R="$PY -m phase3.rl --config configs/phase4_rl.yaml --exp 4.4 --seed ${SEED:?set SEED}"
               $R
               $R --set rl.objective_params.beta=0
               $R --set rl.objective_params.floor=-75.6
               $R --set rl.ref_kl=0.01
               $R --set rl.objective=filtered
               $R --set rl.objective=self_diffusion
               $R --set rl.objective=grpo ;;
    # 4.4 horizon check: one wd1 run of 1,000 steps
    rl44-h)    $PY -m phase3.rl --config configs/phase4_rl.yaml --exp 4.4 --seed 0 --tag _h1000 --set rl.max_rl_steps=1000 ;;
    # 4.5a factorial on floored wd1: order (fixed / sampled, tau_o 0.05) x weights (group / batch).
    # The fixed-order, group cell is the floored arm of 4.4. One launch per arm (three seeds in parallel).
    rl45a-ord|rl45a-batch|rl45a-both)
               local R="$PY -m phase3.rl --config configs/phase4_rl.yaml --exp 4.5a --seed ${SEED:?set SEED} --set rl.objective_params.floor=-75.6"
               case "$what" in
                 rl45a-ord)   $R rl.order_temp=0.05 ;;
                 rl45a-batch) $R rl.weights_over=batch ;;
                 rl45a-both)  $R rl.order_temp=0.05 rl.weights_over=batch ;;
               esac ;;
    # 4.6c regime map for the push-down term (docs/RL_DLLM_DIRECTIONS.md, direction 2), one launch per arm,
    # three seeds side by side. r1-r3: one change each against 4.4 / 4.5a. r4-r5: dense reward (uses labels).
    # r6-r8: 2 sampler steps in rollouts and evaluation.
    rl46-r1|rl46-r2|rl46-r3|rl46-r4|rl46-r5|rl46-r6|rl46-r7|rl46-r8)
               local R="$PY -m phase3.rl --config configs/phase4_rl.yaml --exp 4.6c --seed ${SEED:?set SEED}"
               case "$what" in
                 rl46-r1) $R --set rl.weights_over=batch rl.objective_params.beta=0 ;;
                 rl46-r2) $R --tag _mu1 --set rl.inner_steps=1 ;;
                 rl46-r3) $R --tag _paperopt --set rl.lr=3e-6 rl.grad_clip=0.2 rl.weight_decay=0.1 ;;
                 rl46-r4) $R --set rl.reward=cell_accuracy ;;
                 rl46-r5) $R --set rl.reward=cell_accuracy rl.objective_params.beta=0 ;;
                 rl46-r6) $R --tag _s2 --set rl.rollout_steps=2 ;;
                 rl46-r7) $R --tag _s2 --set rl.rollout_steps=2 rl.objective_params.beta=0 ;;
                 rl46-r8) $R --tag _s2 --set rl.rollout_steps=2 rl.objective=filtered ;;
               esac ;;
    # 4.6d what self-training learns (direction 4): the supervised objective on all puzzles / on solved ones
    rl46-sup-all|rl46-sup-solved|rl46-sup-unsolved)
               $PY -m phase3.rl --config configs/phase4_rl.yaml --exp 4.6d --seed "${SEED:?set SEED}" \
                 --set rl.objective=supervised "rl.supervised_on=${what#rl46-sup-}" ;;
    *) echo "unknown launch: $what" >&2; exit 1 ;;
  esac
}
main "$@"
